:root {
  --bg: #1a3d2b;
  --bg-light: #274f38;
  --accent: #5dbf7a;
  --accent-dim: #3a8f55;
  --text-light: #e8f5ee;
  --text-muted: #9ec9ad;
  --status-bg: #5dbf7a;
  --status-text: #1a3d2b;
  --tag-bg: #274f38;
  --tag-border: #3a8f55;
  --divider: #3a8f55;
}

.license-badge {
  background-color: var(--bg);
  border: 2px solid var(--accent-dim);
  border-radius: 16px;
  padding: 20px;
  width: 380px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.badge-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.badge-icon {
  font-size: 32px;
  line-height: 1;
}

.badge-title {
  flex: 1;
}

.badge-title h1 {
  font-size: 18px;
  font-weight: 700;
  color: var(--text-light);
  margin: 0;
  line-height: 1.2;
}

.badge-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 2px 0 0 0;
}

.badge-status {
  background-color: var(--status-bg);
  color: var(--status-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 20px;
}

.badge-body {
  background-color: var(--bg-light);
  border-radius: 10px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--divider);
  padding-bottom: 8px;
}

.info-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.info-label {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 500;
}

.info-value {
  font-size: 13px;
  color: var(--text-light);
  font-weight: 600;
}

.badge-footer {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.zone-tag {
  background-color: var(--tag-bg);
  border: 1px solid var(--tag-border);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
}
